mapper.select:
SELECT id,command_id,serial_id,sku_id,pick_fact_id,balance_id,shipment_ref,owner_epoch,state,claim_epoch,attempts
FROM serial_shipment_intent WHERE enterprise_id=#{e} AND warehouse_id=#{w}
AND state IN ('PENDING','RUNNING') AND next_attempt_at <= #{now}
ORDER BY next_attempt_at,id LIMIT 1 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE local_serial SET state='SHIPPED',version=version+1,updated_at=#{row.now}
WHERE enterprise_id=#{row.e} AND warehouse_id=#{row.w} AND serial_id=#{row.serial} AND sku_id=#{row.sku}
  AND owner_epoch=#{row.epoch} AND balance_id=#{row.balance} AND state='AUTHORIZED' AND registry_state='ACTIVE'

UPDATE local_serial SET registry_state='SHIPPED',registry_error=NULL,version=version+1,updated_at=#{row.now}
WHERE enterprise_id=#{row.e} AND warehouse_id=#{row.w} AND serial_id=#{row.serial} AND sku_id=#{row.sku}
  AND owner_epoch=#{row.epoch} AND balance_id=#{row.balance} AND state='SHIPPED' AND registry_state<>'SHIPPED'
